foreach ($key in $sourceMethods.Keys | Sort-Object) {
  $src = $sourceMethods[$key]
  if ($docMethods.ContainsKey($key)) {
    $doc = $docMethods[$key]
  } else {
    $doc = @()
  }
  $missing = $src | Where-Object { $doc -notcontains $_ }
  if ($missing.Count -gt 0) {
    Write-Output "$key : MISSING $($missing.Count) => $($missing -join ', ')"
  } else {
    Write-Output "$key : OK"
  }
}